const GRAMMAR_YE_FORMS=["gaf","ngaf","liv","gav","afdax","angxngaiv","har","laiv","sav","gof","nier","sixbax","hxexsex","bifzixkar","longvkar","cov","woftux","lov","xief","gexzex","hufnix","enrzouf","gerdix","cixpux","hxer","cerlar","karcov","lofbuxcer","arbax","arniex","lovdiex","bor","hurrix","mefcaf","mefzer","karkor","laf","hur","sox","pix","qierbif","ongx","daf","hxeflax","yer","zif","rar","laov","nif","cefsif","buf","mor","aixdix","havlier","langfgax","rex","longr","taxniex","bifkuix","div","lir","lax","sef","liex","enrqief","angfnix","gev","wovtar","box","xivcar","haxcex","wox","jiux","tortor","horlier","sov","caif","arxief","muvnier","hxerbar","nierxif","cer","lier","cafdixcafgaf","lafbiex","sif","niex","ongxgar","gafdox","gaif","gaifhur","gafdoxhur","gartixhur","gafhur","gafhurlar","gaflax","gaflaxhur","gafbox","gaflaxniex","gafjixhur","gafjixboxlux","gafboxlux","gafliao","gafliex","gafboxlax","hor","sar","tav","biuf","miefjianx","souf","boxlir","dor","nief","tongfqianr","ma","zir","hox","kaxbiexliex","caf","avser","o","sextongx","xiaof","zuf","longx","qinrmox","kax","hxif","taxtix","a","ongr","tongf","xif","lix","qier","xir","anf","tavhar","niexxix","paiv","xix","dief","naiv","taif","gavliaor","kar","pux","zaf","soflix","ni","halie","pu","xi","niexi","sa","nga","haosi","qiebi","na","boli","go","pibo","wuf","kav","gercif","enrzir","songxkox","liaox","rur","tax","meftaxcer","sax","i","suanv","cixtux","cux","rof","nierbar","davxiv","lof","buxzix","rix","youf","tongv","aixliex","pev","buv","wav","qif","kuaiv","zofzix","yif","zangx","ngafdor","angfdor","nifdor","sefdor","gofdor","gexdor","angf","gex"];
